"""T7 执行层占位（E2）：Executor 协议 + Manual（v1 唯一实现）+ Broker 占位。

软件只出信号与建议，买点/执行由人决定；feedback 闭环记录采纳/放弃。
"""
from __future__ import annotations

from datetime import date
from typing import Protocol

from lkl.models.types import Signal
from lkl.utils import db


class ExecResult:
    def __init__(self, order_id: str, status: str) -> None:
        self.order_id, self.status = order_id, status


class Executor(Protocol):
    """执行器协议：P4 起 QMT/easytrader 按此接入。"""

    def submit(self, sig: Signal) -> ExecResult: ...

    def status(self, order_id: str) -> ExecResult: ...


class ManualExecutor:
    """v1 唯一实现：不委托，信号保持 SUGGESTED 等人工回执。"""

    def submit(self, sig: Signal) -> ExecResult:
        return ExecResult(f"manual-{sig.confirm_date}-{sig.code}", "SUGGESTED")

    def status(self, order_id: str) -> ExecResult:
        return ExecResult(order_id, "SUGGESTED")


class BrokerExecutor:
    """占位（P4）：接入 QMT/easytrader 前禁止实例化使用。"""

    def submit(self, sig: Signal) -> ExecResult:
        raise NotImplementedError("P4 接入 QMT/easytrader")

    def status(self, order_id: str) -> ExecResult:
        raise NotImplementedError("P4 接入 QMT/easytrader")


def feedback(confirm_date: date, code: str, action: str,
             status: str, price: float | None = None) -> int:
    """人工回执：SUGGESTED → ADOPTED/DROPPED（评估期统计采纳率）。"""
    if status not in ("ADOPTED", "DROPPED"):
        raise ValueError("status 仅支持 ADOPTED/DROPPED")
    return db.execute(
        "UPDATE signal SET status=%s, feedback_price=%s, feedback_date=%s"
        " WHERE confirm_date=%s AND code=%s AND action=%s",
        (status, price, confirm_date, confirm_date, code, action))

