"""掘金仿真凭据与接入配置：env 优先，回退 gitignored 的 .secrets/gm.env。

遵循仓库纪律（同 ~/.dbconfig）：token/account_id 不入库不入代码。
"""
from __future__ import annotations

import os
from pathlib import Path

SECRETS_FILE = Path(__file__).resolve().parents[2] / ".secrets" / "gm.env"
ENDPOINT_DEFAULT = "api.myquant.cn:9000"


def _file_values() -> dict:
    if not SECRETS_FILE.exists():
        return {}
    out: dict[str, str] = {}
    for line in SECRETS_FILE.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        out[key.strip()] = value.strip()
    return out


def token() -> str:
    """掘金用户 token（身份识别，等同账号+密码）。"""
    return os.environ.get("GM_TOKEN") or _load_file().get("GM_TOKEN", "")


def account_id() -> str:
    return os.environ.get("GM_ACCOUNT_ID") or _load_file().get("GM_ACCOUNT_ID", "")


def endpoint() -> str:
    chosen = os.environ.get("GM_ENDPOINT") or _load_file().get("GM_ENDPOINT", "")
    return chosen or ENDPOINT_DEFAULT


_load_file = None  # placeholder replaced below to keep eager import cheap
del _load_file


def endpoint_ok() -> bool:
    """本机到仿真服务端点的连通性预检（TCP 只测端口，不等 SDK）。"""
    import socket
    host, _, port = endpoint().rpartition(":")
    try:
        sock = socket.create_connection((host, int(port)), timeout=5)
        sock.close()
        return True
    except OSError:
        return False

