TOKEN = "588bbd0713713de3d468290830007aaf27dc7133"
ACCT = "98b35d21-a6bb-11f1-9282-00163e022aa6"

def try_get(url, headers, label):
    req = urllib.request.Request(url, headers=headers)
    try:
        r = urllib.request.urlopen(req, timeout=10)
        body = r.read()
        print(f"[{label}] {url} -> {r.status} {body[:160]}")
        return r.status, body
    except urllib.error.HTTPError as e:
        print(f"[{label}] {url} -> HTTP {e.code} {e.read()[:120]}")
    except Exception as e:
        print(f"[{label}] {url} -> {repr(e)[:110]}")
    return None, None

