import urllib.request, json
TOKEN="588bbd0713713de3d468290830007aaf27dc7133"
hosts=["https://www.myquant.cn","https://sim.myquant.cn"]
paths=["/api/v1/accounts","/v1/accounts","/api/account/info","/api/user/info",
       "/v1/user","/api/v1/user/info","/api/accounts","/user/account-list","/v3/accounts/list"]
def probe(url, extra):
    h={'User-Agent':'Mozilla/5.0','Accept':'application/json','Content-Type':'application/json'}
    h.update(extra)
    req=urllib.request.Request(url,headers=h)
    try:
        r=urllib.request.urlopen(req,timeout=8); b=r.read()[:150]; ct=r.headers.get('Content-Type','')
        kind='JSON' if 'json' in ct else 'HTML'
        print(f"[{kind}] {url}  ct={ct}  {b}")
    except urllib.error.HTTPError as e:
        print(f"[HTTP {e.code}] {url}  {e.headers.get('Content-Type')} {e.read()[:100]}")
    except Exception as e:
        print(f"[fail] {url} {repr(e)[:60]}")
auths=[("token",{'token':TOKTOKEN}),("bearer",{'Authorization':'Bearer '+TOKTOKEN}),
       ("token-hdr",{'X-Token':TOKTOKEN}),("nobody",{})]
for p in paths:
    for h,lab in auths:
        if 'www' in hosts[0]:
            probe(hosts[0]+p,h,lab); break
    break
# concise: only a few combos
for p in ['/api/v1/accounts','/v1/accounts','/api/user/info','/user/does-login']:
    for h,lab in auths:
