"""lkl sim CLI：info 拉账户资金/持仓；order 下单；orders 查委托。"""
from __future__ import annotations

from datetime import date

from lkl.broker import config, reachability
from lkl.models.types import Signal
from lkl.services.execution import BrokerExecutor


def _ready() -> int | None:
    """凭据/端点预检；不满足返回退出码提示。"""
    if not config.token() or not config.account_id():
        print("未配置凭据：写入 .secrets/gm.env 或设 GM_TOKEN/GM_ACCOUNT_ID")
        return 2
    if not reachability.endpoint_reachable(config.endpoint()):
        print(f"⚠ 端点 {config.endpoint()} 不可达：请启动金矿终端并连接账户")
        return 3
    return None


def _info() -> None:
    from lkl.broker.info import user_info
    u = user_info()
    cash = u.cash
    print(f"账户 {u.account_id}" + (f" {u.account_name}" if u.account_name else ""))
    if cash:
        print(f"  资产净值 {cash.nav:.2f} | 总资产 {cash.balance:.2f} | "
              f"可用 {cash.available:.2f} | 冻结 {cash.frozen:.2f} | 浮盈 {cash.pnl:.2f}")
    else:
        print("  资金：未取得")
    if not u.positions:
        print("  持仓：空")
    else:
        print("  持仓：")
        for p in u.positions:
            print(f"    {p.symbol} x{p.volume} 可用{p.available} "
                  f"成本{p.cost} 现价{p.last_price} 浮盈{p.fpnl}")


def _order(argv: list[str]) -> None:
    if len(argv) < 2:
        print("用法: lkl sim order <code> <BUY|SELL> [股数=100]")
        return
    code, side = argv[0].upper(), argv[1].upper()
    shares = int(argv[2]) if len(argv) > 2 else 0
    sig = Signal(confirm_date=date.today(), code=code, action=side)
    res = BrokerExecutor().submit(sig, volume=shares)
    print(f"下单 {side} {code} -> {res}")


def _orders() -> None:
    from lkl.broker.orders import list_status
    for row in list_status():
        print(f"  {row.order_id} {row.status}")


def run(argv: list[str]) -> int:
    """lkl sim 分发：info(默认)/order/orders。"""
    err = _precheck()
    if err:
        return err
    action = argv[0] if argv else "info"
    try:
        if action == "order":
            _order(argv[1:])
        elif action == "orders":
            _orders()
        else:
            _info()
    except ConnectionError as e:
        print(f"连接失败：{e}")
        return 1
    return 0

