"""实时委托：Signal → 掘金 gmtrade order_volume；订单状态查询。

BUY 默认 1 手(100 股)；SELL 平掉持仓可用量。执行前须本地金矿终端已连账户。
"""
from __future__ import annotations

from gmtrade.api import (
    OrderSide_Buy, OrderSide_Sell, OrderType_Market,
    PositionEffect_Open, PositionEffect_Close, get_orders, order_volume,
)
from lkl.broker import client, queries, symbol
from lkl.models.types import Signal
from lkl.services.execution import ExecResult

_DEFAULT_LOT = 100  # BUY 默认 1 手
_EFFECT = {  # Signal.action → (OrderSide, PositionEffect)
    "BUY": (OrderSide_Buy, PositionEffect_Open),
    "SELL": (OrderSide_Sell, PositionEffect_Close),
}
_LABEL = {1: "已报", 2: "部成", 3: "已成", 4: "当日收",
          5: "已撤", 6: "待撤", 8: "已拒", 10: "待报", 12: "过期"}


def _lot(sig: Signal) -> int:
    """SELL 用持仓可用量；BUY 用默认 1 手。"""
    if sig.action != "SELL":
        return _DEFAULT_LOT
    gm = symbol.to_gm_symbol(sig.code)
    for p in queries.positions():
        if p.symbol == gm and p.available > 0:
            return p.available
    return 0


def submit(sig: Signal, volume: int = 0) -> ExecResult:
    """按 Signal 下单，返回委托结果。"""
    client.connect()
    side, effect = _EFFECT[sig.action]
    shares = volume or _lot(sig)
    if shares <= 0:
        return ExecResult("", "NO_POSITION")
    orders = order_volume(symbol.to_gm_symbol(sig.code), shares, side,
                          OrderType_Market, effect, price=0.0)
    if not orders:
        return ExecResult("", "REJECTED")
    o = orders[0]
    label = _LABEL.get(o.status, f"ST{o.status}")
    return ExecResult(o.order_id, label)


def get_status(order_id: str) -> ExecResult:
    """按 order_id 查当日委托状态。"""
    client.connect()
    for o in _orders():
        if o.order_id == order_id or o.cl_ord_id == order_id:
            return ExecResult(o.order_id, _label(o))
    return ExecResult(order_id, "NOT_FOUND")


def list_status() -> list:
    """今日全部委托的(id, 状态) 结果列表。"""
    client.connect()
    return [ExecResult(o.order_id, _label(o)) for o in _orders()]


def _orders() -> list:
    """原始委托列表（避免与上方 get_orders 混淆）。"""
    return get_orders()


def _label(o) -> str:
    return _LABEL.get(o.status, f"ST{o.status}")

