"""T6 卖出建议（PLAN §1.6，基于 R4 手动实仓；只出建议不代执行）。

优先级：b 退潮清仓 > a 断板卖出；高潮/分歧期持有不动（c 规则=不产生建议）。
"""
from __future__ import annotations

import logging
from datetime import date

from lkl.models.types import DerivedBar, Position, Signal
from lkl.services import position
from lkl.utils import db

log = logging.getLogger("lkl.exit")


def _stat(trade_date: date) -> dict | None:
    df = db.query_df("SELECT phase, buy_window, force_liquidate FROM market_stat"
                     " WHERE date = %s", (trade_date,))
    return None if df.empty else df.iloc[0].to_dict()


def _derived(trade_date: date, code: str) -> DerivedBar | None:
    df = db.query_df("SELECT code, date, is_limit_up, is_one_word, cont_days"
                     " FROM derived_bar WHERE date = %s AND code = %s",
                     (trade_date, code))
    if df.empty:
        return None
    r = df.iloc[0]
    return DerivedBar(code=r.code, date=r.date, is_limit_up=bool(r.is_limit_up),
                      is_one_word=bool(r.is_one_word), cont_days=int(r.cont_days))


def liquidate_check(pos: Position, stat: dict) -> Signal | None:
    """b 退潮清仓：force_liquidate=True → 无条件建议卖出。"""
    if not stat or not stat["force_liquidate"]:
        return None
    return Signal(confirm_date=pos.entry_date, code=pos.code, action="SELL",
                  reason="退潮期清仓建议（优先级最高）", buy_window="NONE")


def broken_board_check(pos: Position, day: DerivedBar | None) -> Signal | None:
    """a 断板建议：持仓股今日未封住涨停 → 建议卖出（一字断板同样适用）。"""
    if day is None or day.is_limit_up:
        return None
    return Signal(confirm_date=day.date, code=pos.code, action="SELL",
                  reason=f"断板建议（原{day.cont_days or ''}连板今日未封）",
                  buy_window="")


def suggestions(trade_date: date) -> list[Signal]:
    """当日全部卖出建议：退潮清仓优先，否则逐仓断板检查。"""
    stat = _stat(trade_date)
    open_pos = position.current()
    if stat and stat["force_liquidate"]:
        out = [s for p in open_pos if (s := liquidate_check(p, stat))]
        for s in out:
            s.confirm_date = trade_date
        return out
    out = []
    for p in open_pos:
        s = broken_board_check(p, _derived(trade_date, p.code))
        if s:
            out.append(s)
    return out

