"""本地交易 CLI 入口（with-trade 精简版）：sim 查询/手动下单，trade 自动交易。

策略生成在 DB 侧服务器 -> 经 JSON(e.g.~/trade/decisions.json)通道驱动本机实单。
"""
from __future__ import annotations

import argparse
import logging
import sys


def _sim(argv: list[str]) -> int:
    """lkl sim [info|order|orders]：连接本地金矿终端查询/手动下单。"""
    from lkl.broker import cli
    return cli.run(argv)


def _trade(argv: list[str]) -> int:
    """lkl trade [YYYY-MM-DD]：按 decisions.json 自动实单并写 results.json。"""
    from lkl.broker import trader
    return trader.run(argv)


_COMMANDS = {
    "sim":   (_sim, "掘金仿真：info 账户/资金/持仓 | order <code> <BUY|SELL> [股数] | orders"),
    "trade": (_trade, "自动交易：读 decisions.json 逐条实单，写 results.json"),
}


def main(argv: list[str] | None = None) -> int:
    """解析 -> 查表 -> 调用。"""
    logging.basicConfig(level=logging.INFO,
                        format="%(asctime)s %(name)s %(levelname)s %(message)s")
    argv = list(sys.argv[1:] if argv is None else argv)
    parser = argparse.ArgumentParser(prog="lkl", description="本地自动交易")
    sub = parser.add_subparsers(dest="command", metavar="<command>")
    for name, (_fn, help_text) in _COMMANDS.items():
        sub.add_parser(name, help=help_text)
    args, rest = parser.parse_known_args(argv)
    if not args.command:
        parser.print_help()
        return 1
    return _COMMANDS[args.command][0](rest)


if __name__ == "__main__":
    raise SystemExit(main())

