"""JSON 交易通道：读 decisions.json、写 results.json（不落库；schema v1）。

交换目录默认 ~/trade（env TRADE_DIR 可覆盖），由两机同步工具搬运。
"""
from __future__ import annotations

import json
import os
from datetime import date
from pathlib import Path

from lkl.models.types import Signal

_SCHEMA = 1


def directory() -> Path:
