"""交易三文件一致性核对：decisions/results/holdings 的日期 vs 今日(Shanghai)。"""
from __future__ import annotations

from lkl.broker import exchange, fileio, trade_date


def _label(when: str | None, today: str) -> str:
    if when is None:
        return "缺文件"
    if when == today:
        return "今日 ✓"
    return f"过期/错日({when}) ✗"


def run() -> int:
    """打印三文件交易日期与今日比对；全一致返回 0。"""
    today = trade_date.trade_date()
    d = fileio.read("decisions.json")
    r = fileio.read("results.json")
    h = fileio.read("holdings.json")
    bad = []
    for name, data in (("decisions", d), ("results", r), ("holdings", h)):
        when = data.get("for_date") or data.get("trade_date")
        tag = _label2(when) if False else _label(when, today)
        if when != today:
            bad.append(name)
        print(f"  {name:10} for_date={when or '-':12} {tag} (今日={today})")
    if not d.get("for_date"):
        print("  (decisions 缺——本机不会执行)")
    refs = {(it.get("action"), it.get("code")) for it in d.get("actions", [])}
    done = {(t.get("action"), t.get("code")) for t in r.get("trades", [])}
    missing = refs - done
    print(f"  决策{len(refs)} 条 / 已回报 {len(done)} 条 / 缺回报 {sorted(missing)}"
          if missing else f"  决策{len(refs)} 条已全部回报 ✓")
