"""A股交易时段判定（一律 Asia/Shanghai）。"""
from __future__ import annotations

from datetime import datetime, time
from zoneinfo import ZoneInfo

TZ = ZoneInfo("Asia/Shanghai")

_MORNING = (time(9, 30), time(11, 30))
_AFTERNOON = (time(13, 0), time(15, 0))


def now() -> datetime:
    return datetime.now(TZ)


def is_open(dt: datetime | None = None) -> bool:
    """当前处于连续竞价时段。"""
    t = (dt or now()).time()
    return t >= _MORNING[0] and t <= _MORNING[1] or\
           t >= _AFTERNOON[0] and t <= _AFTERNOON[1]


def pre_open(dt: datetime | None = None) -> bool:
    """盘前：08:00~09:30（可做持仓快照/对账）。"""
    t = (dt or now()).time()
    return time(8, 0) <= t < time(9, 30)


def wait_at_until(interval: int) -> float:
    """返回下次必须醒来的秒数（盘中=interval，盘外最长 60s）。"""
    return float(interval if is_trading(now()) else 60)

"""金矿终端就绪门：轮询 7001，未达则等待不报错（供 supervisor 用）。"""
from __future__ import annotations

import time

from lkl.broker import config, reachability

_RETRY = 30


def up() -> bool:
    """终端服务此刻可达？"""
    return reachability.endpoint_reachable(config.endpoint())


def wait(timeout: float = 300.0, step: float = 5.0) -> bool:
    """等到终端可达或超时；返回最终是否就绪。"""
    end = time.time() + timeout
    while time.time() < end:
        if up():
            return True
        time.sleep(step)
    return up()

