<html lang="zh">
<head><meta charset="utf-8"><title>LKL 交易看板</title>
<style>
body{font-family:system-ui;margin:2rem;background:#f7f8fa;color:#222}
h1{font-size:1.3rem}h2{font-size:1rem;margin:1.3rem 0 .4rem}
#tabs{display:flex;gap:.4rem;border-bottom:2px solid #dde;margin-bottom:1rem}
.tab{padding:.45rem 1.1rem;cursor:pointer;border:1px solid #dde;border-bottom:none;border-radius:8px 8px 0 0;background:#eee}
.tab.on{background:#fff;font-weight:600;border-top:2px solid #2a6}
.screen{display:none}.screen.on{display:block}
.card{background:#fff;border:1px solid #e3e5e8;border-radius:8px;padding:.6rem 1rem;margin:.4rem 0}
table{border-collapse:collapse;width:100%}
td,th{border:1px solid #e3e5e8;padding:4px 8px;font-size:.9rem;text-align:left}
.ok{color:#0a7d2b}.bad{color:#c0392b}.mid{color:#b07d00}.sub{color:#666;font-size:.8rem;margin:.2rem 0}
.cash b{margin-right:1.2rem}
.pill{display:inline-block;padding:1px 8px;border-radius:10px;font-size:.8rem}
.pill.o{background:#e6f4ea;color:#0a7d2b}.pill.x{background:#fdeaea;color:#c0392b}.pill.m{background:#fdf3e3;color:#b07d00}
</style></head>
<body>
<h1>LKL 交易看板</h1>
<div id="tabs">
  <div class="tab on" data-v="trade" onclick="show('trade')">股票交易</div>
  <div class="tab" data-v="sys" onclick="show('sys')">系统运行状态</div>
</div>
<p id="stat" class="sub">加载中…</p>

<section id="trade" class="screen on">
  <h2>账户</h2><div class="card" id="account">-</div>
  <h2>当日待执行（decisions）</h2><div class="card" id="decisions">-</div>
  <h2>成交回报（results）</h2><div class="card" id="results">-</div>
  <h2>今日委托</h2><div class="card" id="orders">-</div>
</section>

<section id="sys" class="screen">
  <h2>运行环境</h2><div class="card" id="env">-</div>
  <h2>交换目录文件</h2><div class="card" id="files">-</div>
</section>

<script>
function $(id){return document.getElementById(id)}
function show(v){
  document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('on',t.dataset.v===v));
  document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('on',s.id===v));
  (v==='sys')?loadSys():load();
}
async function load(){
  const s=await (await fetch('/api/state')).json();
  $('stat').textContent=`for_date ${s.for_date} · 交换目录 ${s.exchange_dir} · 每5s刷新`;
  renderAccount(s.account); renderTable('decisions',s.decisions,['action','code','reason','window']);
  renderResults(s.results); renderTable('orders',s.orders,['id','status']);
}
async function loadSys(){
  const s=await (await fetch('/api/sys')).json();
  $('stat').textContent=`${s.now} · ${s.phase} · ${s.exchange_dir} · 每5s刷新`;
  const term=`<span class="pill ${s.terminal==='在线'?'o':'x'}">终端 ${s.terminal}</span> `+
    `<span class="pill ${s.account_ready?'o':'x'}">账户 ${s.account_ready?'已连':'未连接'}</span>`;
  $('env').innerHTML=`<div class="cash"><b>端点 ${s.endpoint}</b><b>${term}</b></div>`;
  const keys=['exists','size','mtime','today','schema','for_date'];
  const th='<tr><th>文件</th>'+keys.map(k=>`<th>${k}</th>`).join('')+'</tr>';
  const rows=Object.entries(s.files).map(([n,f])=>{
    const ok=f.exists&&f.today;
    return `<tr><td>${n}</td><td class="${f.exists?'ok':'bad'}">${f.exists?'有':'缺'}</td>`+
      keys.slice(1).map(k=>{ if(k==='today')return `<td class="${f.exists?(f.today?'ok':'mid'):'sub'}">${f.exists?(f.today?'✓':'陈旧'):'—'}</td>`;
        return `<td>${val(f[k])}</td>`; }).join('')+'</tr>'; }).join('');
  $('files').innerHTML='<table>'+th+rows+'</table>';
}
function renderAccount(a){
  const el=$('account');
  if(!a.ok){ el.innerHTML=`<span class="bad">未连接：${a.note||''}</span>`; return; }
  const c=a.cash||{};
  el.innerHTML=`<div class="cash"><b>资产净值 ¥${num(c.nav)}</b><b>总资产 ¥${num(c.balance)}</b>`+
    `<b>可用 ¥${num(c.available)}</b><b>冻结 ¥${num(c.frozen)}</b><b>浮盈 ¥${num(c.pnl)}</b></div>`+
    (a.positions&&a.positions.length?`<table><tr><th>代码</th><th>数量</th><th>可用</th><th>成本</th><th>现价</th><th>浮盈</th></tr>`
    +a.positions.map(p=>`<tr><td>${p.symbol}</td><td>${p.volume}</td><td>${p.available}</td><td>${p.cost}</td><td>${p.last_price}</td><td>${p.fpnl}</td></tr>`).join('')+'</table>':'<p class="sub">持仓：空</p>');
}
function renderTable(id,rows,keys){
  const el=$(id); if(!rows||!rows.length){ el.innerHTML='<p class="sub">空</p>'; return; }
  el.innerHTML='<table><tr>'+keys.map(k=>`<th>${k}</th>`).join('')+'</tr>'
    +rows.map(r=>'<tr>'+keys.map(k=>`<td>${val(r[k])}</td>`).join('')+'</tr>').join('')+'</table>';
}
function renderResults(rows){
  const el=$('results'); if(!rows||!rows.length){ el.innerHTML='<p class="sub">空</p>'; return; }
  el.innerHTML='<table><tr><th>动作</th><th>代码</th><th>结果</th><th>状态</th><th>委托号</th></tr>'
    +rows.map(t=>`<tr><td>${t.action}</td><td>${t.code}</td><td class="${t.ok?'ok':'bad'}">${t.ok?'成交':'未成'}</td><td>${t.status}</td><td>${t.order_id}</td></tr>`).join('');
}
const num=x=>x==null?'—':Number(x).toFixed(2);
const val=x=>x==null?'—':x;
load(); loadSys(); setInterval(()=>{load();loadSys();},5000);
</script>
</body></html>", "i": "Rewrite dashboard HTML with two tabs", "path": "E:/2026Workplace/Code/LKL-Trade/dashboard/trade_index.html"}

