"""远端策略交换目录 SSH 同步：拉/推「最新带时间戳」文件（env 开关，免手工拷贝）。"""
from __future__ import annotations

import logging
import subprocess

from lkl.broker import config, fileio

log = logging.getLogger("lkl.remote")


def enabled() -> bool:
    return bool(config.remote_host())


def _target() -> str:
    return f"{config.remote_host()}:{config.remote_dir()}"


def _dir() -> str:
    return config.remote_dir()


def _ssh(cmd: list) -> str:
    return subprocess.run(["ssh", "-o", "BatchMode=yes", "-o", "ConnectTimeout=10",
                           "-i", str(config.remote_key()), config.remote_host(), *cmd],
                          capture_output=True, text=True).stdout.strip()


def _scp(args: list) -> bool:
    base = ["scp", "-q", "-o", "BatchMode=yes", "-o", "ConnectTimeout=10",
            "-o", "StrictHostKeyChecking=accept-new", "-i", str(config.remote_key())]
    return subprocess.run(base + args, timeout=30, capture_output=True).returncode == 0


def _newest(kind: str) -> str:
    """远端最新 basename；无则 ''。"""
    return _ssh(["sh", "-c", f"ls -1t {_dir()}/{kind}_*.json 2>/dev/null | head -n1"])


def rm(base: str) -> bool:
    if not enabled() or not base:
        return True
    return _ssh(["sh", "-c", f"rm -f '{_dir()}/{base}'"]) or True


def pull(kind: str) -> bool:
    """远端最新 {kind}_*.json → 本地同名；未启用/无可拉返回 True。"""
    if not enabled():
        return True
    base = _newest(kind)
    if not base:
        return True
    ok = _scp([f"{_target()}/{base}", str(fileio.directory() / base)])
    if not ok:
        log.warning("拉取远端 %s 失败", base)
    return ok


def push(kind: str) -> bool:
    """本地最新 {kind}_*.json → 远端；未启用返回 True。"""
    if not enabled():
        return True
    p = fileio.latest(kind)
    if not p:
        return True
    ok = _scp([str(p), f"{_target()}/"])
    if not ok:
        log.warning("推送远端 %s 失败", p.name)
